// Keys returns the map's keys.
func Keys[K comparable, V any](m map[K]V) []K {
	keys := make([]K, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	return keys
}

// Process streams records from any reader.
func Process[R io.Reader](r R, batch int) error {
	dec := json.NewDecoder(r)
	for dec.More() {
		var rec Record
		if err := dec.Decode(&rec); err != nil {
			return err
		}
		apply(rec)
	}
	return nil
}

// Cache is a typed in-memory cache.
type Cache[K comparable, V any] struct {
	mu sync.Mutex
	m  map[K]V
}
